use super::*;
struct Source<'a>(&'a serde_json::Value);
impl Source<'_>{fn delta(&self,step:usize)->&serde_json::Value{&self.0["steps"][step]}}
impl ChainedSource for Source<'_>{
 fn held_len(&self)->usize{self.0["held"].as_array().unwrap().len()}fn held_key(&self,i:usize)->&str{self.0["held"][i].as_str().unwrap()}fn steps_len(&self)->usize{self.0["steps"].as_array().unwrap().len()}
 fn removed_len(&self,s:usize)->usize{self.delta(s)["removed"].as_array().unwrap().len()}fn removed(&self,s:usize,i:usize)->(&str,usize){let row=&self.delta(s)["removed"][i];(row["id"].as_str().unwrap(),row["index"].as_u64().unwrap() as usize)}
 fn inserted_len(&self,s:usize)->usize{self.delta(s)["inserted"].as_array().unwrap().len()}fn inserted(&self,s:usize,i:usize)->(&str,usize){let row=&self.delta(s)["inserted"][i];(row["id"].as_str().unwrap(),row["index"].as_u64().unwrap() as usize)}
 fn moved_len(&self,s:usize)->usize{self.delta(s)["moved"].as_array().unwrap().len()}fn moved(&self,s:usize,i:usize)->(&str,usize,usize){let row=&self.delta(s)["moved"][i];(row["id"].as_str().unwrap(),row["from"].as_u64().unwrap() as usize,row["to"].as_u64().unwrap() as usize)}
 fn modified_len(&self,s:usize)->usize{self.delta(s)["modified"].as_array().unwrap().len()}fn modified_key(&self,s:usize,i:usize)->&str{self.delta(s)["modified"][i]["id"].as_str().unwrap()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(plan:&mut ChainedPlan){plan.begin_close();for _ in 0..100000{if plan.terminal_is_empty(){return}let d=plan.close_demand();assert_eq!(plan.close_step(Default::default()).unwrap(),Default::default());plan.close_step(grant(d)).unwrap();}panic!("chained numeric close stalled")}
fn address(value:&serde_json::Value)->Address{Address{step:value[0].as_u64().map(|v|v as usize),row:value[1].as_u64().unwrap() as usize}}
#[test]
fn every_nested_prefix_preserves_original_identity_and_refusal(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let s=Source(row);let mut plan=ChainedPlan::new();let mut turns=0usize;loop{let d=plan.demand(&s).unwrap();for axis in 0..5{let mut short=grant(d);match axis{0=>short.maximum_items=0,1=>short.maximum_copy_bytes=d.copy_bytes-1,2=>{if d.capacity_bytes==0{continue}short.maximum_capacity_bytes=d.capacity_bytes-1},3=>{if d.release_bytes==0{continue}short.maximum_release_bytes=d.release_bytes-1},_=>short.maximum_depth=d.depth-1}assert_eq!(plan.advance(&s,short).unwrap().progress,Default::default());}let step=plan.advance(&s,grant(d)).unwrap();turns+=1;assert!(turns<100000);if let Some(error)=step.error{assert_eq!(error,row["error"].as_str().unwrap());break}if step.done{assert!(row.get("error").is_none());let origins:Vec<_>=row["origins"].as_array().unwrap().iter().map(address).collect();assert_eq!(plan.origins().unwrap(),origins.as_slice());let modifications:Vec<_>=row["modifications"].as_array().unwrap().iter().map(|row|Modification{target:address(&row[0]),step:row[1].as_u64().unwrap() as usize,index:row[2].as_u64().unwrap() as usize}).collect();assert_eq!(plan.modifications().unwrap(),modifications.as_slice());break}}close(&mut plan);for cut in[0,1,7,turns.saturating_sub(1)]{let mut plan=ChainedPlan::new();for _ in 0..cut{let d=plan.demand(&s).unwrap();let step=plan.advance(&s,grant(d)).unwrap();if step.done||step.error.is_some(){break}}close(&mut plan)}}}
